Example: The following program demonstrates complete abstraction using a pure abstract class.
#include <iostream>
using namespace std;
// Pure Abstract Class acting as an Interface
class Printable {
public:
    virtual void print() = 0;  // pure virtual function
    virtual void scan() = 0;   // pure virtual function
    // Virtual destructor is a good practice for base classes
    virtual ~Printable() {}
};
// Derived class must implement all functions
class Document : public Printable {

Printable() {}
};
// Derived class must implement all functions
class Document : public Printable {
public:
    void print() override {
        cout << "Printing document..." << endl;
    }
    void scan() override {
        cout << "Scanning document..." << endl;
    }
};
// Another derived class implementing the same interface
class Photo : public Printable {
public:
    void print() override {
        cout << "Printing photo..." << endl;
    }
    void scan() override {
        cout << "Scanning photo..." << endl;
    }
};
int main() {
    // Base class pointer pointing to derived objects

ning photo..." << endl;
    }
};
int main() {
    // Base class pointer pointing to derived objects
    Printable* p1 = new Document();
    Printable* p2 = new Photo();
    // Call interface functions - runtime polymorphism
    p1->print();
    p1->scan();
    p2->print();
    p2->scan();
    // Free memory
    delete p1;
    delete p2;
    return 0;
}
Output
Printing document...
Scanning document...
Printing photo...
Scanning photo...
Explanation
- Printable is a pure abstract class that defines the operations print() and scan().
- Document and Photo implement these operations differently.

xample of abstraction. It simplifies the interaction with a TV by hiding all the complex technology. We don't need to understand how the TV internally works; we just need to press the button to change the channel or adjust the volume.
abstract class TV{

    abstract void turnOn();
    abstract void turnOff();
}
// Concrete class implementing the abstract methods
class TVRemote extends TV{

    @Override
    void turnOn(){

        System.out.println("TV is turned ON.");
    }
    @Override
    void turnOff(){

        System.out.println("TV is turned OFF.");
    }
}

@Override
    void turnOff(){

        System.out.println("TV is turned OFF.");
    }
}
// Main class to demonstrate abstraction
public class Geeks{

    public static void main(String[] args){

        TV remote = new TVRemote();
        remote.turnOn();   
        remote.turnOff();  
    }
}
Output
TV is turned ON.
TV is turned OFF.
Explanation:
- TV is abstract class defining turnOn() and turnOff() methods.
- TVRemote class implements the abstract methods with specific logic.

